formulas.expression:
{!Get_Opportunity.Opportunity_Number__c} & " - Renewal - " & IF( LEN( {!Get_Opportunity.Opportunity_Number__c} & " - Renewal - " & {!Get_Opportunity.Account.Name} & " - " & {!Get_Opportunity.Facility__r.Name} & " - " & TEXT({!Get_Opportunity.Modality__c}) & " - " & TEXT(TODAY()) ) > 120,
/* Truncate Account and Facility to stay under 120 */ LEFT({!Get_Opportunity.Account.Name}, 25) & " - " & LEFT({!Get_Opportunity.Facility__r.Name}, 25) & " - " & TEXT({!Get_Opportunity.Modality__c}) & " - " & TEXT(TODAY()),
/* Full version if under 120 */ {!Get_Opportunity.Account.Name} & " - " & {!Get_Opportunity.Facility__r.Name} & " - " & TEXT({!Get_Opportunity.Modality__c}) & " - " & TEXT(TODAY()) )
